    @keyframes fadeIn { from { opacity: 0; transform: translateY(4px); } to { opacity: 1; transform: translateY(0); } }

    .sim-layout { display: grid; grid-template-columns: 430px 1fr; gap: 22px; align-items: start; }
    @media (max-width: 992px) {
