    body.mobile-only-mode .topbar,
    body.mobile-only-mode .desktop-companion-col {
      display: none !important;
    }
    body.mobile-only-mode .container-main {
      padding: 0;
      max-width: 100%;
    }
    body.mobile-only-mode .sim-layout {
      grid-template-columns: 1fr;
    }
    body.mobile-only-mode .phone-frame {
      width: 100vw;
      height: 100vh;
      border: none;
      border-radius: 0;
    }

    .phone-notch {
      height: 26px;
      background: var(--bg-surface);
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 0 18px;
