    /* 1. STICKY HEADER WITH INSTANT GDPR PILL & THEME SWITCHER (No Scrolling Required!) */
    .phone-header {
      padding: 9px 12px;
      background: var(--bg-surface);
      border-bottom: 1px solid var(--border-color);
      display: flex;
      justify-content: space-between;
      align-items: center;
      gap: 6px;
      flex-shrink: 0;
      position: relative;
      z-index: 50;
    }
    .hdr-chip {
