      border-color: rgba(16, 185, 129, 0.4);
    }

    /* 3. BURGER MENU NAVIGATION DRAWER (REPLACES CLUTTERED TOP TAB ROW) */
    .burger-btn {
      width: 32px;
      height: 32px;
      border-radius: 9px;
      border: 1px solid var(--border-color);
      background: var(--bg-surface-2);
      color: var(--text-main);
      display: inline-flex;
      align-items: center;
      justify-content: center;
      font-size: 16px;
      cursor: pointer;
      transition: all 0.18s ease;
      flex-shrink: 0;
    }
    .burger-btn:hover, .burger-btn.active {
      background: var(--primary);
      color: #fff;
      border-color: var(--primary);
    }
    .burger-backdrop {
      position: absolute;
      inset: 0;
      background: rgba(2, 6, 23, 0.62);
      backdrop-filter: blur(3px);
      z-index: 55;
      opacity: 0;
      pointer-events: none;
      transition: opacity 0.22s ease;
    }
    .burger-backdrop.open {
      opacity: 1;
      pointer-events: auto;
    }
    .burger-drawer {
      position: absolute;
      top: 0;
      bottom: 0;
      left: 0;
      width: 78%;
      max-width: 300px;
      background: var(--bg-surface);
      border-right: 1.5px solid var(--primary);
      box-shadow: 16px 0 45px rgba(0,0,0,0.65);
      z-index: 60;
      transform: translateX(-104%);
      transition: transform 0.26s cubic-bezier(0.22, 1, 0.36, 1);
      display: flex;
      flex-direction: column;
      overflow-y: auto;
    }
    .burger-drawer.open {
      transform: translateX(0);
    }
    .burger-item {
      width: 100%;
      padding: 10px 14px;
      border: none;
      background: transparent;
      color: var(--text-secondary);
      font-size: 12px;
      font-weight: 700;
      text-align: left;
      display: flex;
      align-items: center;
      justify-content: space-between;
