      font-weight: 600;
      text-align: left;
      display: flex;
      align-items: center;
      justify-content: space-between;
      border-radius: 8px;
      cursor: pointer;
      margin-bottom: 2px;
    }
    .burger-subitem:hover, .burger-subitem.active {
