      padding: 5px;
      border-radius: 12px;
      border: 1px solid var(--border-color);
      margin-bottom: 10px;
      position: relative;
      z-index: 5;
      box-shadow: var(--card-shadow);
    }
    .seg-btn {
      padding: 7px 4px;
      border-radius: 8px;
      border: none;
      background: transparent;
      color: var(--text-muted);
      font-size: 10.5px;
      font-weight: 700;
      cursor: pointer;
      transition: all 0.18s ease;
      text-align: center;
      white-space: nowrap;
    }
    .seg-btn.active {
      background: var(--primary);
      color: #fff;
      box-shadow: 0 2px 8px rgba(0,0,0,0.2);
    }

    /* Multi-Select Dropdown Component (Locations, Target Roles, Core Skills) */
    .ms-dropdown-wrap {
      position: relative;
      width: 100%;
    }
    .ms-trigger {
      width: 100%;
      min-height: 33px;
      background: var(--bg-surface-2);
      border: 1px solid var(--border-color);
      border-radius: 8px;
      padding: 5px 8px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 6px;
      cursor: pointer;
      font-size: 10.5px;
      color: var(--text-main);
    }
    .ms-trigger:hover {
      border-color: var(--primary);
    }
    .ms-chips {
      display: flex;
      flex-wrap: wrap;
      gap: 4px;
      flex: 1;
    }
    .ms-chip {
      display: inline-flex;
      align-items: center;
      gap: 4px;
      padding: 2px 6px;
      border-radius: 6px;
      background: var(--primary-soft);
      color: var(--primary);
      border: 1px solid rgba(99, 102, 241, 0.35);
      font-size: 9.5px;
      font-weight: 700;
    }
    .ms-chip-rm {
      cursor: pointer;
      font-weight: 900;
      opacity: 0.85;
    }
    .ms-menu {
      position: relative;
      margin-top: 4px;
      background: var(--bg-surface);
