      color: var(--text-main);
      cursor: pointer;
    }
    .ms-opt:hover {
      background: var(--bg-surface-2);
    }

    /* Smooth Cards & Controls */
    .m-card {
      background: var(--bg-surface);
      border: 1px solid var(--border-color);
      border-radius: 14px;
      padding: 11px 12px;
      margin-bottom: 10px;
      box-shadow: var(--card-shadow);
      transition: transform 0.15s ease, border-color 0.15s ease;
    }
    .m-btn {
      padding: 6px 10px;
      border-radius: 8px;
      border: 1px solid transparent;
      font-size: 11px;
      font-weight: 700;
      cursor: pointer;
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 4px;
      transition: all 0.15s ease;
    }
    .m-btn:active { transform: scale(0.96); }
    .m-btn-primary { background: var(--primary); color: #fff; }
    .m-btn-success { background: var(--success); color: #fff; }
    .m-btn-danger { background: var(--danger-soft); color: var(--danger); border-color: rgba(244,63,94,0.3); }
    .m-btn-warning { background: var(--warning-soft); color: var(--warning); border-color: rgba(245,158,11,0.3); }
    .m-btn-ghost { background: var(--bg-surface-2); color: var(--text-secondary); border-color: var(--border-color); }

    /* ==========================================================================
       2.4 INTERACTIVE SWIPE DECK FOR JOBS
       ========================================================================== */
    .swipe-stage {
      position: relative;
      min-height: 395px;
      margin-bottom: 10px;
      perspective: 1000px;
      user-select: none;
    }
    .swipe-card-bg2 {
      position: absolute;
      top: 14px; left: 16px; right: 16px; bottom: 0;
      background: var(--bg-surface-2);
      border: 1px solid var(--border-color);
      border-radius: 20px;
      transform: scale(0.92) translateY(12px);
      opacity: 0.45;
      z-index: 1;
      pointer-events: none;
    }
    .swipe-card-bg1 {
      position: absolute;
      top: 7px; left: 8px; right: 8px; bottom: 0;
      background: var(--bg-surface);
      border: 1px solid var(--border-color);
      border-radius: 20px;
      transform: scale(0.96) translateY(6px);
      opacity: 0.75;
      z-index: 2;
      pointer-events: none;
    }
    .swipe-card {
      position: relative;
      z-index: 3;
      background: var(--bg-surface);
      border: 1.5px solid var(--border-color);
      border-radius: 20px;
      padding: 15px;
      box-shadow: 0 16px 38px rgba(0,0,0,0.35);
      cursor: grab;
      transition: transform 0.28s cubic-bezier(0.22, 1, 0.36, 1), opacity 0.25s ease;
      touch-action: pan-y;
    }
    .swipe-card:active { cursor: grabbing; }
    .swipe-stamp {
      position: absolute;
      top: 18px;
      padding: 4px 12px;
      border-radius: 8px;
      font-size: 14px;
      font-weight: 900;
      letter-spacing: 1px;
      text-transform: uppercase;
      opacity: 0;
      pointer-events: none;
      transition: opacity 0.12s ease;
      z-index: 10;
    }
    .swipe-stamp.approve {
      left: 16px;
      color: #10b981;
      border: 3px solid #10b981;
      background: rgba(16, 185, 129, 0.15);
      transform: rotate(-12deg);
    }
    .swipe-stamp.nope {
      right: 16px;
      color: #f43f5e;
      border: 3px solid #f43f5e;
      background: rgba(244, 63, 94, 0.15);
      transform: rotate(12deg);
    }
    .swipe-dock {
      display: flex;
      justify-content: center;
      align-items: center;
      gap: 10px;
      padding: 6px 0 4px 0;
    }
    .swipe-fab {
      width: 46px;
      height: 46px;
      border-radius: 50%;
      border: 1.5px solid var(--border-color);
      background: var(--bg-surface);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 18px;
      cursor: pointer;
      box-shadow: 0 6px 18px rgba(0,0,0,0.28);
      transition: all 0.18s cubic-bezier(0.22, 1, 0.36, 1);
    }
    .swipe-fab:hover { transform: scale(1.08); }
    .swipe-fab:active { transform: scale(0.93); }
    .swipe-fab.pass { color: #f43f5e; border-color: rgba(244,63,94,0.4); }
    .swipe-fab.info { color: #38bdf8; border-color: rgba(56,189,248,0.4); width: 42px; height: 42px; font-size: 15px; }
    .swipe-fab.like { color: #10b981; border-color: rgba(16,185,129,0.45); width: 52px; height: 52px; font-size: 21px; }
    .swipe-fab.super { color: #a855f7; border-color: rgba(168,85,247,0.4); width: 42px; height: 42px; font-size: 15px; }

    /* ==========================================================================
       2.5 LEFT-TO-RIGHT HALF-SCREEN SLIDER (PULLS FROM LEFT TO HALF SCREEN!)
       ========================================================================== */
    .left-edge-pull-tab {
      position: absolute;
      left: 0;
      top: 52%;
      transform: translateY(-50%);
      background: linear-gradient(180deg, var(--primary), var(--accent));
      color: #ffffff;
      padding: 11px 5px;
      border-radius: 0 11px 11px 0;
      font-size: 9.5px;
      font-weight: 800;
      writing-mode: vertical-rl;
      text-orientation: mixed;
      cursor: pointer;
      z-index: 38;
      box-shadow: 4px 0 16px rgba(99, 102, 241, 0.45);
      border: 1px solid rgba(255,255,255,0.28);
      border-left: none;
      letter-spacing: 0.6px;
      transition: all 0.2s ease;
      user-select: none;
    }
    .left-edge-pull-tab:hover { padding-right: 8px; }

    .slider-backdrop {
      position: absolute;
      top: 71px;
      left: 0;
      right: 0;
      bottom: 0;
      background: rgba(2, 6, 23, 0.38);
      z-index: 39;
      display: none;
      cursor: pointer;
    }
    .slider-backdrop.open {
      display: block;
    }

    .half-slider {
      position: absolute;
      top: 71px;
      bottom: 0;
      left: 0;
      width: 75%;
      background: var(--bg-glass);
      backdrop-filter: blur(18px);
      -webkit-backdrop-filter: blur(18px);
      border-right: 2.5px solid var(--primary);
      border-radius: 0 20px 20px 0;
      box-shadow: 16px 0 42px rgba(0,0,0,0.62);
      z-index: 40;
      display: flex;
      flex-direction: column;
      transition: transform 0.26s cubic-bezier(0.22, 1, 0.36, 1);
      overflow: hidden;
    }
    .half-slider.state-closed {
      transform: translateX(-104%);
      pointer-events: none;
    }
    .half-slider.state-half,
    .half-slider.state-open,
    .half-slider.state-full {
      width: 75%;
      transform: translateX(0);
    }

    .slider-right-edge-grip {
      position: absolute;
      right: 0;
      top: 50%;
      transform: translateY(-50%);
      width: 18px;
      height: 68px;
      background: var(--primary);
      color: #fff;
      border-radius: 8px 0 0 8px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 10px;
      font-weight: 800;
      cursor: pointer;
      z-index: 45;
      box-shadow: -2px 0 10px rgba(0,0,0,0.35);
      user-select: none;
    }

    .slider-handle-bar {
      padding: 8px 10px;
      background: var(--bg-surface);
      border-bottom: 1px solid var(--border-color);
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 6px;
      flex-shrink: 0;
    }
    .slider-body {
      flex: 1;
      overflow-y: auto;
      padding: 9px 14px 18px 10px;
    }

