      j.clHtml = `<p>Dear ${escH(j.hrName || 'Hiring Team')},</p><p>I am writing to apply for the <strong>${escH(j.role || j.title)}</strong> role at <strong>${escH(j.company)}</strong>. In my work building production analytics pipelines across <strong>SQL, Python, Tableau, and ${escH(addedKeywords)}</strong>, I partner with product and commercial leaders to turn complex datasets into measurable revenue and retention outcomes.</p><p>I would welcome the opportunity to discuss how my background aligns with ${escH(j.company)}'s roadmap.</p><p>Sincerely,<br>Sumanto Banerjee</p>`;

      const newRel = computeJdRelevanceBreakdown(j);
      notifyToast(`🚀 Injected JD keywords (${addedKeywords})! Resume: ${newRel.resumeScore}% • Cover Letter: ${newRel.clScore}%`);
