    // NAVIGATION & HALF-SLIDER CONTROLLER
    // =========================================================================
    const PHONE_TAB_TITLES = {
      funnel: 'Dashboard',
      jobs: 'Job Discovery Deck',
      a4: 'Resume & Cover Letter',
      portals: 'Portals & Auth Vault',
      linkedin: 'LinkedIn Hub',
      profile: 'Profile & Master CV',
      settings: 'App & AI Settings',
      gdpr: 'GDPR Center'
    };

    let previousPhoneTab = 'funnel';

    function setPhoneTab(tab) {
      if (tab && tab !== currentPhoneTab) {
        previousPhoneTab = currentPhoneTab;
      }
      currentPhoneTab = tab;
      toggleBurgerMenu(false);
      document.querySelectorAll('.burger-item[data-ptab]').forEach(b => {
        b.classList.toggle('active', b.getAttribute('data-ptab') === tab);
      });
      const titleEl = document.getElementById('phone-active-title');
      if (titleEl) titleEl.textContent = PHONE_TAB_TITLES[tab] || 'CareerPulse AI';
      const backBtn = document.getElementById('phone-back-btn');
      if (backBtn) backBtn.style.display = (tab === 'funnel') ? 'none' : 'inline-flex';

      if (tab !== 'jobs') {
        sliderState = 'closed';
      }
      renderSimulator();
      renderHalfSlider();
    }

    function goBackPhoneTab() {
      const target = (previousPhoneTab && previousPhoneTab !== currentPhoneTab) ? previousPhoneTab : 'funnel';
      setPhoneTab(target);
    }

    function setSliderState(st) {
      if (currentPhoneTab !== 'jobs') {
        sliderState = 'closed';
      } else {
        sliderState = (st === 'closed') ? 'closed' : 'half';
      }
      const isJobs = currentPhoneTab === 'jobs';
      const el = document.getElementById('phone-half-slider');
      if (el) {
        el.className = 'half-slider state-' + (isJobs ? sliderState : 'closed');
        el.style.display = isJobs ? 'flex' : 'none';
      }
      const bd = document.getElementById('phone-slider-backdrop');
      if (bd) bd.classList.toggle('open', isJobs && sliderState !== 'closed');
      const pullTab = document.getElementById('left-edge-pull-tab');
      if (pullTab) pullTab.style.display = (isJobs && sliderState === 'closed') ? 'block' : 'none';
      renderSimulator();
      renderHalfSlider();
    }

    function cycleSliderHeight() {
      if (currentPhoneTab !== 'jobs') return;
      setSliderState(sliderState === 'closed' ? 'half' : 'closed');
    }

    // Requirement 2.4: Clicking on a job NEVER switches the tab! Instead it selects the job and opens the 75% Left Slider right over the Job Discovery Deck.
    function inspectJobWithoutTabChange(sNo) {
      selectedJobSno = String(sNo);
      setSliderState('half');
      renderSimulator();
    }

    function getSelectedJob() {
      const jobs = (liveState && liveState.jobs) || [];
      return jobs.find(j => String(j.sNo) === String(selectedJobSno)) || jobs[0] || {};
    }

    // =========================================================================
    // 2.6 FILTER & SORT ENGINE FOR JOBS
    // =========================================================================
    function getFilteredSortedJobs() {
      const jobs = ((liveState && liveState.jobs) || []).slice();
      const filtered = jobs.filter(j => {
        if (jobFilterCompany !== 'ALL' && String(j.company || '').trim() !== jobFilterCompany) return false;
        if (jobFilterPosition !== 'ALL') {
          const cat = String(j.roleCategory || j.category || '').trim();
          const role = String(j.role || j.title || '').toLowerCase();
          if (cat !== jobFilterPosition && !role.includes(jobFilterPosition.toLowerCase())) return false;
        }
        if (jobFilterStatus !== 'ALL') {
          const st = String(j.status || '') + ' ' + String(j.stageBucket || '');
          if (jobFilterStatus === 'AUTO_APPLIED') {
            const p = String(j.portal || '').toLowerCase();
            if (!/applied/i.test(st) || !(p.includes('linkedin') || p.includes('naukri') || p.includes('instahyre') || p.includes('wellfound') || (Number(j.sNoNum || j.sNo || 0) % 3 !== 0))) return false;
          } else if (!st.toLowerCase().includes(jobFilterStatus.toLowerCase())) {
            return false;
          }
        }
        if (jobSearchQuery) {
          const q = jobSearchQuery.toLowerCase();
          const hay = `${j.company || ''} ${j.role || j.title || ''} ${j.portal || ''} ${j.location || ''}`.toLowerCase();
          if (!hay.includes(q)) return false;
        }
        return true;
      });

      filtered.sort((a, b) => {
        const snoA = Number(a.sNoNum || a.sNo || 0);
        const snoB = Number(b.sNoNum || b.sNo || 0);
        if (jobSortBy === 'chrono_desc') return snoB - snoA;
        if (jobSortBy === 'chrono_asc') return snoA - snoB;
        if (jobSortBy === 'company_asc') return String(a.company || '').localeCompare(String(b.company || ''));
        if (jobSortBy === 'company_desc') return String(b.company || '').localeCompare(String(a.company || ''));
        if (jobSortBy === 'pos_asc') return String(a.role || a.title || '').localeCompare(String(b.role || b.title || ''));
        if (jobSortBy === 'pos_desc') return String(b.role || b.title || '').localeCompare(String(a.role || a.title || ''));
        if (jobSortBy === 'match_desc') {
          const scoreA = computeJdRelevanceBreakdown(a).resumeScore;
          const scoreB = computeJdRelevanceBreakdown(b).resumeScore;
          return scoreB - scoreA;
        }
        return 0;
      });
      return filtered;
    }

    function updateJobFilter(field, val) {
      if (field === 'company') jobFilterCompany = val;
      if (field === 'position') jobFilterPosition = val;
      if (field === 'status') jobFilterStatus = val;
      if (field === 'search') jobSearchQuery = val;
      if (field === 'sort') jobSortBy = val;
      swipeCursor = 0;
      const list = getFilteredSortedJobs();
      if (list.length > 0) selectedJobSno = String(list[0].sNo);
      renderSimulator();
      if (sliderState !== 'closed') renderHalfSlider();
    }

    function resetJobFilters() {
      jobFilterCompany = 'ALL';
      jobFilterPosition = 'ALL';
      jobFilterStatus = 'ALL';
      jobSearchQuery = '';
      jobSortBy = 'chrono_desc';
      swipeCursor = 0;
      renderSimulator();
    }

