        sliderEl.style.display = isJobs ? 'flex' : 'none';
      }
      const bd = document.getElementById('phone-slider-backdrop');
      if (bd) bd.classList.toggle('open', isJobs && sliderState !== 'closed');
      const pullTab = document.getElementById('left-edge-pull-tab');
      if (pullTab) pullTab.style.display = (isJobs && sliderState === 'closed') ? 'block' : 'none';

      if (currentPhoneTab === 'funnel') {
        renderMobileDashboardTab(body);
      } else if (currentPhoneTab === 'jobs') {
        renderMobileJobsTab(body);
      } else if (currentPhoneTab === 'a4') {
        renderMobileA4ResumeTab(body);
      } else if (currentPhoneTab === 'portals') {
        renderMobilePortalsTab(body);
      } else if (currentPhoneTab === 'linkedin') {
        renderMobileLinkedInTab(body);
      } else if (currentPhoneTab === 'profile') {
        renderMobileProfileTab(body);
      } else if (currentPhoneTab === 'settings') {
        renderMobileSettingsTab(body);
      } else if (currentPhoneTab === 'gdpr') {
        renderMobileGdprTab(body);
      }
    }

