        body.innerHTML = topBarHtml + `
          <div style="font-size:10px;color:var(--text-muted);margin-bottom:6px;">
            Tap any job to pull out the <strong>Left Half-Slider (JD, Relevance Score % &amp; Controls)</strong> without leaving this tab:
