    function attachSwipeTouchHandlers() {
      const card = document.getElementById('active-swipe-card');
      if (!card) return;
      let startX = 0, currentX = 0, dragging = false;
      const stampApprove = document.getElementById('stamp-approve');
      const stampNope = document.getElementById('stamp-nope');

      const onDown = (e) => {
        if (e.target.closest('button')) return;
        dragging = true;
        startX = e.clientX || (e.touches && e.touches[0].clientX) || 0;
        currentX = startX;
        card.style.transition = 'none';
      };
      const onMove = (e) => {
        if (!dragging) return;
        currentX = e.clientX || (e.touches && e.touches[0].clientX) || startX;
        const dx = currentX - startX;
        const rot = dx * 0.06;
        card.style.transform = `translate3d(${dx}px, 0, 0) rotate(${rot}deg)`;
        if (stampApprove) stampApprove.style.opacity = dx > 25 ? Math.min(1, (dx - 25) / 70) : 0;
        if (stampNope) stampNope.style.opacity = dx < -25 ? Math.min(1, (-dx - 25) / 70) : 0;
      };
      const onUp = () => {
        if (!dragging) return;
        dragging = false;
        const dx = currentX - startX;
        card.style.transition = 'transform 0.28s cubic-bezier(0.22, 1, 0.36, 1), opacity 0.25s ease';
        if (dx > 85) {
          triggerDeckSwipe('right', selectedJobSno);
        } else if (dx < -85) {
          triggerDeckSwipe('left', selectedJobSno);
        } else {
          card.style.transform = '';
          if (stampApprove) stampApprove.style.opacity = 0;
          if (stampNope) stampNope.style.opacity = 0;
        }
      };

      card.addEventListener('pointerdown', onDown);
      window.addEventListener('pointermove', onMove);
      window.addEventListener('pointerup', onUp);
    }

    // =========================================================================
    // CANDIDATE APPLICATION SIGN-OFF & NON-MISREPRESENTATION CONTROLLER
    // =========================================================================
    let pendingSignoffContext = null; // { sNo, targetStatus, fromSwipeDir }

    function openCandidateSignoffModal(sNo, targetStatus, fromSwipeDir) {
      const jobs = (liveState && liveState.jobs) || [];
      const job = jobs.find(j => String(j.sNo) === String(sNo)) || getSelectedJob();
      pendingSignoffContext = { sNo: String(job.sNo || sNo), targetStatus: targetStatus || 'Approved', fromSwipeDir: fromSwipeDir || null };
      const lbl = document.getElementById('signoff-modal-job-label');
      if (lbl) lbl.textContent = `#${job.sNo} ${job.company || 'Company'} — ${job.role || job.title || 'Target Role'}`;
      const chk = document.getElementById('signoff-modal-checkbox');
      if (chk) chk.checked = Boolean(job._signedOff);
      const modal = document.getElementById('signoff-modal-backdrop');
      if (modal) modal.style.display = 'flex';
      toggleSignoffConfirmBtn();
    }

    function closeCandidateSignoffModal() {
      const modal = document.getElementById('signoff-modal-backdrop');
      if (modal) modal.style.display = 'none';
      pendingSignoffContext = null;
      renderSimulator();
    }

    function toggleSignoffConfirmBtn() {
      const chk = document.getElementById('signoff-modal-checkbox');
      const btn = document.getElementById('signoff-confirm-btn');
      if (!btn) return;
      btn.style.opacity = (chk && chk.checked) ? '1' : '0.55';
    }

    let showA4EditDrawer = false;

    function editResumeBeforeSignoff() {
      const ctx = pendingSignoffContext;
      closeCandidateSignoffModal();
      if (ctx && ctx.sNo) selectedJobSno = String(ctx.sNo);
      if (currentPhoneTab === 'jobs') {
        sliderTab = 'ai';
        setSliderState('half');
      } else {
        showA4EditDrawer = true;
        setPhoneTab('a4');
      }
      notifyToast('Review and modify your Resume & Cover Letter before signing off.');
    }

    function confirmCandidateSignoff() {
      const chk = document.getElementById('signoff-modal-checkbox');
      if (!chk || !chk.checked) {
        notifyToast('Please check the Candidate Sign-Off box to confirm you read the JD and approve the Resume & Cover Letter.');
        return;
      }
      const ctx = pendingSignoffContext || { sNo: selectedJobSno, targetStatus: 'Approved', fromSwipeDir: null };
      const jobs = (liveState && liveState.jobs) || [];
      const job = jobs.find(j => String(j.sNo) === String(ctx.sNo)) || getSelectedJob();
      job._signedOff = true;
      job._signedOffAt = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
      const modal = document.getElementById('signoff-modal-backdrop');
      if (modal) modal.style.display = 'none';
      pendingSignoffContext = null;

      if (ctx.fromSwipeDir) {
        executeDeckSwipeAfterSignoff(ctx.fromSwipeDir, ctx.sNo);
      } else {
        applyJobStatusWithSignoff(ctx.sNo, ctx.targetStatus);
      }
    }

    function approveFromA4WithSignoff(sNo, targetStatus) {
      const jobs = (liveState && liveState.jobs) || [];
      const job = jobs.find(j => String(j.sNo) === String(sNo)) || getSelectedJob();
      const chk = document.getElementById('a4-signoff-chk');
      if (!job._signedOff && (!chk || !chk.checked)) {
        openCandidateSignoffModal(sNo, targetStatus || 'Approved', null);
        return;
      }
      job._signedOff = true;
      job._signedOffAt = job._signedOffAt || new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
      applyJobStatusWithSignoff(sNo, targetStatus || 'Approved');
    }

    async function triggerDeckSwipe(dir, sNo) {
      const filtered = getFilteredSortedJobs();
      const job = filtered.find(j => String(j.sNo) === String(sNo)) || getSelectedJob();
      if ((dir === 'right' || dir === 'auto_apply') && !job._signedOff) {
        openCandidateSignoffModal(sNo, dir === 'auto_apply' ? 'Applied' : 'Approved', dir);
        return;
      }
      executeDeckSwipeAfterSignoff(dir, sNo);
    }

    async function executeDeckSwipeAfterSignoff(dir, sNo) {
      const card = document.getElementById('active-swipe-card');
      const filtered = getFilteredSortedJobs();
      const job = filtered.find(j => String(j.sNo) === String(sNo)) || getSelectedJob();
      swipeHistory.push(swipeCursor);

      if (card) {
        const tx = dir === 'left' ? -420 : 420;
        const rot = dir === 'left' ? -18 : 18;
        card.style.transform = `translate3d(${tx}px, -10px, 0) rotate(${rot}deg)`;
        card.style.opacity = '0';
      }

      if (dir === 'right') {
        job.status = 'Approved';
        job.stageBucket = 'Approved';
        notifyToast(`Signed Off & Approved #${job.sNo} ${job.company}!`);
        callBackendJobAction(job.sNo, 'approve', { candidateSignedOff: true });
      } else if (dir === 'auto_apply') {
        job.status = 'Applied';
        job.stageBucket = 'Applied';
        notifyToast(`Signed Off & Auto-Applied to #${job.sNo} ${job.company}!`);
        callBackendJobAction(job.sNo, 'applied', { candidateSignedOff: true });
      } else {
        job.status = 'Hold / Skip';
        notifyToast(`Passed #${job.sNo} ${job.company}`);
      }

      setTimeout(() => {
        swipeCursor = (swipeCursor + 1) % Math.max(1, filtered.length);
        const nextJob = filtered[swipeCursor];
        if (nextJob) selectedJobSno = String(nextJob.sNo);
        updateCompanionMetrics();
        renderSimulator();
        if (sliderState !== 'closed') renderHalfSlider();
      }, 230);
    }

    function undoDeckSwipe() {
      if (swipeHistory.length === 0) {
        swipeCursor = Math.max(0, swipeCursor - 1);
      } else {
        swipeCursor = swipeHistory.pop();
      }
      const filtered = getFilteredSortedJobs();
