    function togglePortalAuthDrawer(pid) {
      openPortalAuthIds[pid] = !openPortalAuthIds[pid];
      renderSimulator();
    }

    function updatePortalMode(pid, mode) {
      const p = portalVaultState.find(x => x.id === pid);
      if (p) {
        p.mode = mode;
        notifyToast(`Updated ${p.name} → ${mode.replace('_', ' ')}`);
        renderSimulator();
      }
    }

    function authorizePortalNow(pid, methodLabel) {
      const p = portalVaultState.find(x => x.id === pid);
      if (!p) return;
      p.status = 'CONNECTED';
      p.lastSync = 'Just now';
      p.encryption = 'AES-256-GCM (RLS Vault)';
      openPortalAuthIds[pid] = false;
      updateCompanionMetrics();
      notifyToast(`Authorized ${p.name} via ${methodLabel}! Session encrypted in PostgreSQL Vault.`);
      renderSimulator();
    }

    function addCustomCompanyPortal() {
      const name = document.getElementById('new-portal-name')?.value?.trim();
      const domain = document.getElementById('new-portal-domain')?.value?.trim() || 'careers.company.com';
      const kind = document.getElementById('new-portal-kind')?.value || 'company';
      const atsType = document.getElementById('new-portal-ats')?.value || 'Workday Universal SSO';
      const account = document.getElementById('new-portal-user')?.value?.trim() || 'user@example.com';
      if (!name) {
        notifyToast('Please enter a Portal or Company Name');
        return;
      }
      portalVaultState.unshift({
        id: 'CUST-' + Date.now(),
        kind,
        name,
        domain,
        atsType,
        status: 'CONNECTED',
        mode: 'AUTO_APPLY',
        account,
        jobsCount: 1,
        appliedCount: 0,
        lastSync: 'Just now',
        encryption: 'AES-256-GCM (RLS Vault)'
      });
      showAddPortalForm = false;
      portalSubTab = kind === 'portal' ? 'portals' : 'companies';
      updateCompanionMetrics();
      notifyToast(`Added & Authorized ${name} in AES-256-GCM Portal Vault!`);
      renderSimulator();
    }

    function updateJobStageFromSlider(sNo, newStatus) {
      const j = getSelectedJob();
      const slChk = document.getElementById('sl-signoff-chk');
      if (slChk && slChk.checked) {
        j._signedOff = true;
        j._signedOffAt = j._signedOffAt || new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
      }
      if ((newStatus === 'Approved' || newStatus === 'Applied') && !j._signedOff) {
        openCandidateSignoffModal(sNo, newStatus, null);
        return;
      }
      applyJobStatusWithSignoff(sNo, newStatus);
    }

    function applyJobStatusWithSignoff(sNo, newStatus) {
      const jobs = (liveState && liveState.jobs) || [];
      const j = jobs.find(x => String(x.sNo) === String(sNo)) || getSelectedJob();
      j.status = newStatus;
      j.stageBucket = newStatus;
      const mapSub = {
        'Approved': 'approve',
        'Applied': 'applied',
        'Interviewing': 'interviewing',
        'Offer Received': 'offer',
        'Hold / Skip': 'hold',
        'Rejected': 'rejected',
        'Pending Review': 'pending'
      };
      callBackendJobAction(sNo, mapSub[newStatus] || 'set_status', { status: newStatus, candidateSignedOff: Boolean(j._signedOff) });
      notifyToast(`Signed Off & Updated #${sNo} ${j.company} → ${newStatus}`);
      updateCompanionMetrics();
      renderSimulator();
      renderHalfSlider();
    }

    async function submitSliderAiRewrite(sNo) {
      const j = getSelectedJob();
      const docType = document.getElementById('sl-ai-doc')?.value || 'resume';
      const section = document.getElementById('sl-ai-sec')?.value || 'auto';
      const fb = document.getElementById('sl-ai-fb')?.value || 'Emphasize SQL, Python, and business impact';
      notifyToast(`Rewriting ${docType.toUpperCase()} (${section}) for ${j.company}...`);
      try {
        await fetch('/webhook/job-dashboard-api', {
          method: 'POST',
          headers: {'Content-Type': 'application/json'},
          body: JSON.stringify({ action: 'rewrite_doc', sNo: String(sNo), docType, section, feedback: fb, scope: 'GLOBAL' })
        });
      } catch (e) {}
      if (!j.sections) j.sections = {};
      j.sections.summary = `<strong>Senior Data &amp; Business Analyst</strong> tailored for <strong>${escH(j.company)}</strong> (${escH(j.role || j.title)}): ${escH(fb)}. Grounded in production SQL, Python, and executive BI pipelines.`;
      j._boosted = true;
      notifyToast(`Updated ${j.company} ${docType.toUpperCase()} & saved learned rule!`);
      renderSimulator();
      renderHalfSlider();
    }

    function saveSliderReferral(sNo) {
      const j = getSelectedJob();
      j.referralName = document.getElementById('sl-ref-name')?.value || '';
      j.hrName = document.getElementById('sl-hr-name')?.value || '';
      j.reviewerNotes = document.getElementById('sl-notes')?.value || '';
      callBackendJobAction(sNo, 'save_notes', {
        referralName: j.referralName,
        hrName: j.hrName,
        reviewerNotes: j.reviewerNotes
      });
      notifyToast(`Saved Referral (${j.referralName || 'Updated'}) for ${j.company}!`);
      renderSimulator();
      renderHalfSlider();
    }

