    function setLiFbPreset(id, text) {
      const inp = document.getElementById('li-fb-input-' + id);
      if (inp) inp.value = text;
    }

    function toggleFhFeedbackBox(cid) {
      openFhFeedbackIds[cid] = !openFhFeedbackIds[cid];
      renderSimulator();
    }

    function setFhFbPreset(cid, text) {
      const inp = document.getElementById('fh-fb-input-' + cid);
      if (inp) inp.value = text;
    }

    async function handleMobileLiAction(id, subAction) {
      const liLogs = liveState.liLogs || liveState.linkedin || [];
      const item = liLogs.find(x => (x.activity_id || x.id) === id);
      if (item) {
        item.approval_status = subAction === 'approve' ? 'Approved' : 'Rejected / Skipped';
        item.approvalStatus = item.approval_status;
      }
      notifyToast(subAction === 'approve' ? `✅ Approved ${id} & queued for LinkedIn!` : `❌ Rejected ${id}`);
      renderSimulator();
      updateCompanionMetrics();
      try {
        await fetch('/webhook/job-dashboard-api', {
          method: 'POST',
          headers: {'Content-Type': 'application/json'},
          body: JSON.stringify({ action: 'li_action', activityId: id, subAction })
        });
      } catch (e) {}
    }

    async function submitMobileLiFeedback(id) {
      const fb = document.getElementById('li-fb-input-' + id)?.value || 'Keep it under 10 words and natural';
      const liLogs = liveState.liLogs || liveState.linkedin || [];
      const item = liLogs.find(x => (x.activity_id || x.id) === id);
      if (item) {
        const first = String(item.insider_name || item.targetPerson || 'there').split(' ')[0];
        const comp = String(item.company_name || item.company || 'your team').split('/')[0].trim();
        const rewritten = /question/i.test(fb)
          ? `Great point, ${first}—how is this shaping analytics priorities at ${comp}?`
          : `Spot on, ${first}—clean data foundations always win at ${comp}.`;
        item.content_text = rewritten;
        item.draftedContent = rewritten;
        item.approval_status = 'Reworked & Rule Learned';
        item.approvalStatus = 'Reworked & Rule Learned';
      }
      openFeedbackIds[id] = false;
      notifyToast(`✨ Rewrote ${id} with feedback & saved Global Learned Rule!`);
      renderSimulator();
      try {
        await fetch('/webhook/job-dashboard-api', {
          method: 'POST',
          headers: {'Content-Type': 'application/json'},
          body: JSON.stringify({ action: 'li_action', activityId: id, subAction: 'feedback_rewrite', feedback: fb, learnRule: true })
        });
      } catch (e) {}
    }

    async function handleMobileFhAction(cid, subAction) {
      const c = (liveState.fhContacts || []).find(x => x.contact_id === cid);
      if (c) c.approval_status = subAction === 'approve' ? 'Approved' : 'Rejected';
      notifyToast(subAction === 'approve' ? `✅ Approved connection note for ${c?.person_name || cid}!` : `❌ Skipped ${cid}`);
      renderSimulator();
      try {
        await fetch('/webhook/job-dashboard-api', {
          method: 'POST',
          headers: {'Content-Type': 'application/json'},
          body: JSON.stringify({ action: 'fh_action', contactId: cid, subAction })
        });
      } catch (e) {}
    }

    async function submitMobileFhFeedback(cid) {
      const c = (liveState.fhContacts || []).find(x => x.contact_id === cid);
      if (!c) return;
      const fb = document.getElementById('fh-fb-input-' + cid)?.value || 'Make it concise, warm, and tailored to their analytics team';
      const first = String(c.person_name || 'there').split(' ')[0];
      const comp = String(c.company_name || 'your team').split('/')[0].trim();
      const role = String(c.role_title || c.category || 'Analytics').split(',')[0].trim();

      // Immediate intelligent AI-assisted rewrite preview + backend sync
      let rewritten = `Hi ${first}, impressed by your ${role} work at ${comp}—would love to connect!`;
      if (/open role|pointer/i.test(fb)) {
        rewritten = `Hi ${first}, exploring Data & BI roles at ${comp}—would love to connect and learn from your team!`;
      } else if (/short|11|concise/i.test(fb)) {
        rewritten = `Hi ${first}, fellow Data Analyst admiring ${comp}'s analytics—let's connect!`;
      } else if (/referral|advice/i.test(fb)) {
        rewritten = `Hi ${first}, would value your quick advice on ${comp}'s analytics team—happy to connect!`;
      } else if (/sql|bi|peer/i.test(fb)) {
        rewritten = `Hi ${first}, fellow SQL/Python & BI practitioner—would love to connect with you at ${comp}!`;
      } else {
        rewritten = `Hi ${first} (${comp}), ${fb.replace(/^(say|write|mention)\s+/i, '')} — would love to connect!`;
      }

      c.connection_note = rewritten;
      c.approval_status = 'Reworked & Rule Learned';
      openFhFeedbackIds[cid] = false;
      notifyToast(`✨ AI reworked note for ${c.person_name} & saved Global Learned Rule!`);
      renderSimulator();

      try {
        const r = await fetch('/webhook/job-dashboard-api', {
          method: 'POST',
          headers: {'Content-Type': 'application/json'},
          body: JSON.stringify({ action: 'fh_action', contactId: cid, subAction: 'feedback_rewrite', feedback: fb, learnRule: true })
        });
        const d = await r.json();
        if (d && d.ok && d.rewrittenNote) {
          c.connection_note = d.rewrittenNote;
          renderSimulator();
        }
      } catch (e) {}
    }

    async function saveMobileFhDirectEdit(cid) {
      const c = (liveState.fhContacts || []).find(x => x.contact_id === cid);
      if (!c) return;
      const val = document.getElementById('fh-direct-input-' + cid)?.value;
      if (val && val.trim()) {
        c.connection_note = val.trim();
        c.approval_status = 'Edited & Approved';
        openFhFeedbackIds[cid] = false;
        notifyToast(`💾 Saved custom note for ${c.person_name}!`);
        renderSimulator();
        try {
          await fetch('/webhook/job-dashboard-api', {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({ action: 'fh_action', contactId: cid, subAction: 'feedback_rewrite', feedback: val.trim(), learnRule: false })
          });
        } catch (e) {}
      }
    }

    function reactToMilestone(msId, rx) {
      const m = milestoneState.find(x => x.id === msId);
      if (!m) return;
      m.reaction = rx;
      m.reacted = true;
      notifyToast(`${rx} reaction added to ${m.person_name}'s ${m.type} update!`);
      renderSimulator();
    }

    async function sendMilestoneCongrats(msId) {
      const m = milestoneState.find(x => x.id === msId);
      if (!m) return;
      const customText = document.getElementById('ms-input-' + msId)?.value || m.draft;
      m.draft = customText;
