    function formatCtcDisplay(numStr) {
      const clean = String(numStr || '').replace(/[^0-9.]/g, '').trim();
      return clean ? `${clean} LPA` : '';
    }

    function stripCtcLpa(inputEl) {
      if (!inputEl) return;
      inputEl.value = String(inputEl.value || '').replace(/[^0-9.]/g, '').trim();
    }

    function formatCtcWithLpa(inputEl, fieldKey) {
      if (!inputEl) return;
      const clean = String(inputEl.value || '').replace(/[^0-9.]/g, '').trim();
      if (fieldKey) candidateProfileState[fieldKey] = clean;
      inputEl.value = clean ? `${clean} LPA` : '';
      const badgeEl = document.getElementById(inputEl.id + '-badge');
      if (badgeEl) badgeEl.style.display = clean ? 'inline-block' : 'none';
    }

    function handleCtcTyping(inputEl, fieldKey) {
      if (!inputEl) return;
      const clean = String(inputEl.value || '').replace(/[^0-9.]/g, '');
      if (inputEl.value !== clean) inputEl.value = clean;
      if (fieldKey) candidateProfileState[fieldKey] = clean;
      const badgeEl = document.getElementById(inputEl.id + '-badge');
      if (badgeEl) badgeEl.style.display = clean ? 'inline-block' : 'none';
    }

