        const dataUrl = e.target.result;
        candidateProfileState.avatarUrl = dataUrl;
        try { localStorage.setItem('cp_profile_avatar', dataUrl); } catch (err) {}
        updateBurgerProfileAvatar();
        notifyToast('📷 Profile picture updated!');
        renderSimulator();
      };
      reader.readAsDataURL(file);
    }

