    function runSandboxLinkedinClient() {
      const rawUrl = decodeURIComponent(document.getElementById('sb-li-url').value || '');
      const author = (document.getElementById('sb-li-author').value || 'Ashish').split(' ')[0];
      const tpl = document.getElementById('sb-li-tpl').value;
      const age = parseFloat(document.getElementById('sb-li-age').value || '8');
      const post = document.getElementById('sb-li-text').value || '';

      const mUgc = rawUrl.match(/ugcPost:(\d+)/i);
      const mAct = rawUrl.match(/activity:(\d+)/i);
      const mComm = rawUrl.match(/commentUrn=urn:li:comment:\(([^,)]+),(\d+)\)/i);
      const drafts = {
        T1_MISSING_PIECE: `${author}, the AI adoption point misses one piece.. clean baseline definitions.`,
        T2_CLOSING_QUESTION: `For AI adoption, locking clean baseline definitions early saves the most rework.`,
        T4_PRACTITIONER: `When AI models scale in production.. clean schema ownership keeps dashboards honest.`,
        T6_QUOTABLE_REFRAME: `Clean metric definitions always beat throwing more compute at broken pipelines.`,
        SALES_T1_WARMUP: `${author}, sharp point on AI adoption.. clean baseline governance is where teams win.`
      };
      const draft = drafts[tpl] || drafts.T2_CLOSING_QUESTION;
      document.getElementById('sb-li-out').textContent = JSON.stringify({
        ok: true,
        sanitized_prompt_block: `<untrusted_linkedin_data>${post.replace(/ignore all previous instructions/gi, '[REDACTED_DIRECTIVE]')}</untrusted_linkedin_data>`,
        urn_info: {
          post_urn: mUgc ? `urn:li:ugcPost:${mUgc[1]}` : (mAct ? `urn:li:activity:${mAct[1]}` : null),
          top_level_parent_comment_urn: mComm ? `urn:li:comment:(${mComm[1]},${mComm[2]})` : null
        },
        draft_info: {
          template_key: tpl,
          recommended_reaction: tpl === 'T2_CLOSING_QUESTION' || tpl === 'T6_QUOTABLE_REFRAME' ? 'Appreciation (APPRECIATION)' : '💡 Insightful (INTEREST)',
          draft,
          word_count: draft.split(/\s+/).length
        },
        thread_stage: age < 6 ? 'HOT (<6h) — Reply within 90m' : (age <= 24 ? 'WARM (6-24h) — Prime Author-Reply Window' : (age <= 72 ? 'COOL (24-72h)' : 'DORMANT (>72h) -> Escalate to Direct 1-Sentence DM'))
      }, null, 2);
    }

