const BOT_TOKEN = 'YOUR_TELEGRAM_BOT_TOKEN';
const CHAT_ID = '8873019272';
const ALLOWED_EMAILS = ['user@example.com', 'user@example.com', 'user@example.com'];

if (action === 'verify_google_jwt') {
  const jwt = String(reqQuery.credential || '').trim();
  if (!jwt) return [{ json: { status: 'ERROR', message: 'Missing Google OAuth credential token.' } }];
  try {
    const info = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://oauth2.googleapis.com/tokeninfo?id_token=' + encodeURIComponent(jwt),
      json: true
    });
    const email = String(info.email || '').toLowerCase().trim();
    if (info.email_verified === 'true' && ALLOWED_EMAILS.includes(email)) {
      return [{ json: { status: 'AUTHENTICATED', email, name: info.name || 'Sumanto Banerjee', picture: info.picture || '', session_token: 'CAREERPULSE_OAUTH_' + Date.now() } }];
