          <option value="stage:Offer">🏆 Stage: Offer Received (${cnt.offer || 0})</option>
          <option value="stage:Rejected">❌ Stage: Rejected (${cnt.rejected || 0})</option>
          <option value="stage:Needs Rework">🛠️ Stage: Needs Rework (${cnt.needsRework || 0})</option>
          <option value="stage:Skipped / Hold">⏸️ Stage: Skipped / Hold (${cnt.skippedHold || 0})</option>
        </optgroup>
        <optgroup label="🤝 Filter by Referral & HR Contact">
          <option value="ref:HAS_ANY">🤝 Has Referrer or HR Contact (${refCounts.HAS_ANY})</option>
          <option value="ref:DIR_MATCH">📇 Company Has Contacts in LinkedIn Directory (${refCounts.DIR_MATCH})</option>
