    function onMasterFilterChange(val) {
      STATE.masterFilter = val || 'ALL';
      renderMasterTable();
    }

    function resetMasterTableFilter() {
      STATE.masterFilter = 'ALL';
      const sel = document.getElementById('tbl-master-filter');
      if (sel) sel.value = 'ALL';
      const qEl = document.getElementById('tbl-search');
      if (qEl) qEl.value = '';
      renderMasterTable();
    }

    function sortMasterTable(col) {
      if (STATE.tableSortCol === col) STATE.tableSortAsc = !STATE.tableSortAsc;
      else { STATE.tableSortCol = col; STATE.tableSortAsc = false; }
      renderMasterTable();
    }

    function handleMasterRowClick(event, sNo) {
      if (event && event.target && event.target.closest('select, button, a, input, textarea, label')) return;
      openJobInStudio(sNo, 'resume');
    }

    function renderMasterTable() {
      const tbody = document.getElementById('master-table-tbody');
      if (!tbody) return;
      const q = (document.getElementById('tbl-search')?.value || '').toLowerCase().trim();
      const mf = STATE.masterFilter || document.getElementById('tbl-master-filter')?.value || 'ALL';

      let rows = (STATE.jobs || []).filter(j => {
        if (mf !== 'ALL') {
          const [kind, val] = mf.split(':');
          if (kind === 'stage') {
            if (val === 'Re-apply') {
              if (j.stageBucket !== 'Re-apply' && !/re-?apply/i.test(j.status || '')) return false;
            } else if (j.stageBucket !== val) return false;
          } else if (kind === 'company' && j.company !== val) return false;
          else if (kind === 'portal' && j.portal !== val) return false;
          else if (kind === 'res') {
            const rs = String(j.resumeStatus || '');
            const hasCl = Boolean(j.clDriveId || /lgtm|approved|generated|ready/i.test(j.clStatus || ''));
            if (val === 'APPROVED' && !/lgtm|approved/i.test(rs)) return false;
            if (val === 'READY' && /lgtm|approved/i.test(rs)) return false;
            if (val === 'HAS_CL' && !hasCl) return false;
            if (val === 'NO_CL' && hasCl) return false;
          } else if (kind === 'ref') {
            const refStr = `${j.reference || ''} ${j.hrName || ''} ${j.hrEmail || ''} ${j.generalNotes || ''}`.trim();
            if (val === 'HAS_ANY' && !refStr) return false;
            if (val === 'NONE' && refStr) return false;
            if (val === 'REFERRED' && !/referred/i.test(refStr)) return false;
            if (val === 'REQUESTED' && !/seeking|requested/i.test(refStr)) return false;
            if (val === 'HR' && !(j.hrName || j.hrEmail || /hr|recruiter/i.test(refStr))) return false;
            if (val === 'DIR_MATCH' && getMatchedInsidersForCompany(j.company).length === 0) return false;
          }
        }
        if (q) {
          const hay = `${j.sNo} ${j.resumeId} ${j.company} ${j.title} ${j.location} ${j.portal} ${j.status} ${j.resumeStatus} ${j.clStatus} ${j.reference} ${j.hrName} ${j.hrEmail} ${j.generalNotes}`.toLowerCase();
          if (!hay.includes(q)) return false;
        }
        return true;
      });

      const col = STATE.tableSortCol || 'sNoNum';
      const dir = STATE.tableSortAsc ? 1 : -1;
      rows.sort((a, b) => {
        const va = a[col] ?? '';
        const vb = b[col] ?? '';
        if (typeof va === 'number' && typeof vb === 'number') return (va - vb) * dir;
        return String(va).localeCompare(String(vb)) * dir;
      });

      const lbl = document.getElementById('tbl-count-label');
      if (lbl) lbl.textContent = `Showing ${rows.length} of ${STATE.jobs.length} jobs`;

      const refPresetOpts = ['Seeking Referral', 'Referral Requested', 'Referred by Insider', 'HR / Recruiter Contacted', 'Warm Intro Connected'];

      tbody.innerHTML = rows.map(j => {
        const portalUrl = resolveCompanySiteUrl(j);
        const isAppliedLocked = (j.stageBucket === 'Applied' || /applied|submitted/i.test(j.status || '') || Boolean(j.appliedOn)) && !/re-?apply/i.test(j.status || '');
        const matchedInsiders = getMatchedInsidersForCompany(j.company);
        const curRefVal = String(j.reference || '').trim();
        const hasSavedContact = Boolean(curRefVal || j.hrName || j.hrEmail || j.hrPhone);
        const stageOpts = ['Pending Review', 'Approved - Queued for Auto-Apply', 'Applied', 'Re-apply', 'Interviewing', 'Offer Received', 'Rejected', 'Skipped / Hold'];

        return `
        <tr class="clickable-job-row ${String(j.sNo) === String(STATE.selectedSno) ? 'selected-row' : ''}" onclick="handleMasterRowClick(event, '${escHtml(j.sNo)}')" title="Click anywhere on this row to open Job #${escHtml(j.sNo)} (${escHtml(j.company)}) in Split-Screen Studio">
          <td class="mono" style="font-weight:800; color:#38bdf8;">#${escHtml(j.sNo)}</td>
          <td class="mono"><span class="badge b-sky">${escHtml(j.resumeId)}</span></td>
          <td style="font-weight:800; color:#f8fafc;">${escHtml(j.company)}</td>
          <td>
            <div style="font-weight:700; color:#f1f5f9;">${escHtml(j.title)}</div>
            <div style="font-size:11px; color:var(--muted);">${escHtml(j.location)} • ${escHtml(j.roleCategory)}</div>
          </td>
          <td onclick="event.stopPropagation()">
            <a href="${escHtml(portalUrl)}" target="_blank" rel="noopener noreferrer" class="btn btn-sm" style="background:rgba(168,85,247,0.14); border:1px solid rgba(192,132,252,0.45); color:#e9d5ff; font-weight:700; font-size:11px; text-decoration:none; display:inline-flex; align-items:center; gap:4px;" title="Open ${escHtml(j.company)} Career Site: ${escHtml(portalUrl)}">
              🌐 ${escHtml(j.portal || 'Company Site')} ↗
            </a>
          </td>
          <td onclick="event.stopPropagation()">
            <select onchange="quickStageUpdate(this.value, '${escHtml(j.sNo)}')" style="padding:4px 8px; font-size:11.5px; width:auto; border-color:${isAppliedLocked ? '#38bdf8' : 'var(--border)'};">
              ${stageOpts.map(opt => {
                const isSel = (opt === 'Re-apply' && /re-?apply/i.test(j.status || '')) || (opt !== 'Re-apply' && !/re-?apply/i.test(j.status || '') && String(j.status).toLowerCase().includes(opt.split(' ')[0].toLowerCase()));
                const disabledLock = isAppliedLocked && opt === 'Approved - Queued for Auto-Apply';
                const label = opt === 'Applied' && isAppliedLocked ? '🔒 Applied (Locked)' : (opt === 'Re-apply' ? '🔄 Re-apply (Unlock)' : opt);
                return `<option value="${opt}" ${isSel ? 'selected' : ''} ${disabledLock ? 'disabled' : ''}>${label}</option>`;
              }).join('')}
            </select>
            ${isAppliedLocked ? `<div style="font-size:10px; color:#38bdf8; margin-top:2px;">🔒 Won't re-apply unless set to Re-apply</div>` : ''}
          </td>
          <td style="font-size:11.5px;">
            <div>📄 <b>${escHtml(j.resumeStatus || 'Pending')}</b></div>
            <div style="color:#c084fc;">✉️ ${escHtml(j.clStatus || '—')}</div>
          </td>
          <td class="mono" style="font-size:11px; color:var(--muted);">
            <div>C: ${escHtml(j.createdOn || '—')}</div>
            <div style="color:#38bdf8;">U: ${escHtml(j.lastUpdated || '—')}</div>
          </td>
          <td onclick="event.stopPropagation()" style="min-width:215px;">
            <div style="display:flex; flex-direction:column; gap:5px;">
              <select onchange="updateJobReferralDropdown('${escHtml(j.sNo)}', this.value)" style="padding:4px 7px; font-size:11px; width:100%; border-color:${hasSavedContact ? '#34d399' : 'var(--border)'};">
                <option value="">— Select Referral / Insider —</option>
                ${refPresetOpts.map(ro => `<option value="status:${ro}" ${curRefVal === ro ? 'selected' : ''}>${ro}</option>`).join('')}
                ${curRefVal && !refPresetOpts.includes(curRefVal) ? `<option value="custom:${escHtml(curRefVal)}" selected>👤 ${escHtml(curRefVal)}</option>` : ''}
                ${matchedInsiders.length > 0 ? `<optgroup label="📇 ${escHtml(j.company)} Contacts in LinkedIn Directory">` + matchedInsiders.map(mi => `<option value="fh:${escHtml(mi.contact_id)}">👤 ${escHtml(mi.person_name)} (${escHtml(mi.role_title || mi.category)})</option>`).join('') + `</optgroup>` : ''}
              </select>
              <div style="display:flex; align-items:center; justify-content:space-between; gap:5px;">
                <button class="btn btn-sm" style="padding:3px 8px; font-size:10.5px; border-color:${hasSavedContact ? '#34d399' : '#38bdf8'}; color:${hasSavedContact ? '#34d399' : '#38bdf8'}; flex:1;" onclick="openReferralContactModal('${escHtml(j.sNo)}')">
                  👤 ${hasSavedContact ? 'View / Edit Contact' : '+ Contact Info'}
                </button>
                ${matchedInsiders.length > 0 ? `<span class="badge b-emerald" style="font-size:9.5px; cursor:pointer;" onclick="openReferralContactModal('${escHtml(j.sNo)}')" title="${matchedInsiders.length} LinkedIn Directory contact(s) at ${escHtml(j.company)}">${matchedInsiders.length} Insider${matchedInsiders.length>1?'s':''}</span>` : ''}
              </div>
              ${(j.hrName || j.hrEmail) ? `<div style="font-size:10px; color:#94a3b8; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; max-width:200px;">${escHtml(j.hrName || '')} ${j.hrEmail ? '(' + escHtml(j.hrEmail) + ')' : ''}</div>` : ''}
            </div>
          </td>
          <td style="white-space:nowrap;" onclick="event.stopPropagation()">
            <button class="btn btn-sm btn-primary" onclick="openJobInStudio('${escHtml(j.sNo)}', 'resume')">📄 Resume</button>
            <button class="btn btn-sm btn-purple" onclick="openJobInStudio('${escHtml(j.sNo)}', 'cl')">✉️ CL</button>
          </td>
        </tr>
      `;
      }).join('');
    }

    async function updateJobReferralDropdown(sNo, rawVal) {
      const j = (STATE.jobs || []).find(x => String(x.sNo) === String(sNo));
      if (!j) return;
      let reference = '';
      let hrName = j.hrName || '';
      let hrEmail = j.hrEmail || '';
      if (rawVal.startsWith('status:') || rawVal.startsWith('custom:')) {
        reference = rawVal.split(':').slice(1).join(':');
      } else if (rawVal.startsWith('fh:')) {
        const cId = rawVal.slice(3);
        const fc = (STATE.fhContacts || []).find(x => x.contact_id === cId);
        if (fc) {
          reference = `${fc.person_name} (${fc.role_title || fc.category})`;
          if (/hr|recruit|talent/i.test(fc.category || '')) hrName = fc.person_name;
          hrEmail = fc.target_profile_url || hrEmail;
        }
      }
      showToast(`Saving referral for #${sNo} (${j.company})...`, '#38bdf8');
      try {
        const res = await callApi({ action: 'update_job', sNo: String(sNo), subAction: 'set_status', reference, hrName, hrEmail });
        applyApiPayload(res);
        showToast(`Updated referral for #${sNo} (${j.company})!`, '#10b981');
      } catch (e) {
        showToast('Referral update error: ' + e.message, '#f43f5e');
      }
    }

    function openReferralContactModal(sNo) {
      const j = (STATE.jobs || []).find(x => String(x.sNo) === String(sNo));
      if (!j) return;
      STATE.activeRefModalSno = String(sNo);
      document.getElementById('ref-modal-badge').textContent = `Job #${j.sNo} (${j.resumeId}) • ${j.stageBucket}`;
      document.getElementById('ref-modal-title').textContent = `${j.company} — ${j.title}`;
      const refPresets = ['Seeking Referral', 'Referral Requested', 'Referred by Insider', 'HR / Recruiter Contacted', 'Warm Intro Connected'];
      const statusEl = document.getElementById('ref-modal-status');
      if (statusEl) {
        statusEl.value = refPresets.includes(j.reference) ? j.reference : (j.reference ? 'Referred by Insider' : '');
      }
      document.getElementById('ref-modal-reference').value = j.reference || '';
      document.getElementById('ref-modal-hr-name').value = j.hrName || '';
      document.getElementById('ref-modal-hr-email').value = j.hrEmail || '';
      document.getElementById('ref-modal-hr-phone').value = j.hrPhone || '';
      document.getElementById('ref-modal-followup').value = j.followUpDate || '';
      document.getElementById('ref-modal-notes').value = j.generalNotes || '';

      const insiders = getMatchedInsidersForCompany(j.company);
      const insBox = document.getElementById('ref-modal-matched-insiders');
      if (insBox) {
        if (insiders.length > 0) {
          insBox.innerHTML = `
            <div style="background:#090f1d; border:1px solid rgba(52,211,153,0.35); border-radius:10px; padding:10px 12px;">
              <div style="font-size:11.5px; font-weight:800; color:#34d399; margin-bottom:6px;">📇 Matched Insiders & HR at ${escHtml(j.company)} (from your 60+ LinkedIn Directory):</div>
              <div style="display:flex; flex-direction:column; gap:6px; max-height:140px; overflow-y:auto;">
                ${insiders.map(ins => `
                  <div style="display:flex; justify-content:space-between; align-items:center; gap:8px; background:#050913; padding:6px 10px; border-radius:8px; border:1px solid var(--border);">
                    <div>
                      <b style="color:#f8fafc; font-size:12px;">${escHtml(ins.person_name)}</b> <span class="badge b-sky" style="font-size:9.5px;">${escHtml(ins.category)}</span>
                      <div style="font-size:11px; color:var(--muted);">${escHtml(ins.role_title)} • ${escHtml(ins.location || '')}</div>
                    </div>
                    <div style="display:flex; gap:6px; white-space:nowrap;">
                      <a href="${escHtml(ins.target_profile_url)}" target="_blank" class="btn btn-sm" style="font-size:10.5px; color:#38bdf8;">🔗 Profile ↗</a>
                      <button class="btn btn-sm btn-emerald" style="font-size:10.5px;" onclick="applyInsiderToRefModal('${escHtml(ins.contact_id)}')">⚡ Use Contact</button>
                    </div>
                  </div>
                `).join('')}
              </div>
            </div>
          `;
        } else {
          insBox.innerHTML = `<div style="font-size:11.5px; color:var(--muted); background:#090f1d; padding:8px 12px; border-radius:8px; border:1px solid var(--border);">No pre-saved insiders for <b>${escHtml(j.company)}</b> yet — fill in your referrer or HR contact details below to save them.</div>`;
        }
      }
      document.getElementById('referral-contact-modal').style.display = 'flex';
    }

    function applyInsiderToRefModal(contactId) {
      const fc = (STATE.fhContacts || []).find(x => x.contact_id === contactId);
      if (!fc) return;
      const isHr = /hr|recruit|talent/i.test(fc.category || '');
      document.getElementById('ref-modal-status').value = isHr ? 'HR / Recruiter Contacted' : 'Referral Requested';
      document.getElementById('ref-modal-reference').value = `${fc.person_name} (${fc.role_title || fc.category})`;
      if (isHr) document.getElementById('ref-modal-hr-name').value = fc.person_name;
      document.getElementById('ref-modal-hr-email').value = fc.target_profile_url || '';
      showToast(`Filled ${fc.person_name}'s details — click Save Contact Details!`, '#38bdf8');
    }

    function closeReferralContactModal() {
      const m = document.getElementById('referral-contact-modal');
      if (m) m.style.display = 'none';
    }

    function openJobInStudioFromRefModal() {
      const sNo = STATE.activeRefModalSno;
      closeReferralContactModal();
      if (sNo) openJobInStudio(sNo, 'resume');
    }

    async function saveReferralContactModal() {
      const sNo = STATE.activeRefModalSno;
      if (!sNo) return;
      const stVal = (document.getElementById('ref-modal-status')?.value || '').trim();
      const refName = (document.getElementById('ref-modal-reference')?.value || '').trim();
      const finalReference = refName || stVal;
      const hrName = (document.getElementById('ref-modal-hr-name')?.value || '').trim();
      const hrEmail = (document.getElementById('ref-modal-hr-email')?.value || '').trim();
      const hrPhone = (document.getElementById('ref-modal-hr-phone')?.value || '').trim();
      const followUpDate = (document.getElementById('ref-modal-followup')?.value || '').trim();
      const generalNotes = (document.getElementById('ref-modal-notes')?.value || '').trim();
      showToast(`Saving contact details for Job #${sNo}...`, '#38bdf8');
      try {
        const res = await callApi({
          action: 'update_job',
          sNo: String(sNo),
          subAction: 'set_status',
          reference: finalReference,
          hrName,
          hrEmail,
          hrPhone,
          followUpDate,
          generalNotes
        });
        applyApiPayload(res);
        closeReferralContactModal();
        showToast(res.message || `Saved contact details for Job #${sNo}!`, '#10b981');
      } catch (e) {
        showToast('Error saving contact details: ' + e.message, '#f43f5e');
      }
    }

    function openJobInStudio(sNo, docMode) {
      STATE.selectedSno = String(sNo);
      STATE.previewDoc = docMode || 'resume';
      STATE.previewMode = 'sheet';
      const mSel = document.getElementById('studio-mode-select');
      if (mSel) mSel.value = 'sheet';
      switchCmdTab('studio');
      populateStudioJobDropdown();
      switchPreviewDoc(STATE.previewDoc);
    }

    function renderAnalyticsCharts() {
      const box = document.getElementById('analytics-charts-container');
      if (!box) return;
      const c = STATE.counts || {};
      const total = Math.max(1, c.total || STATE.jobs.length || 1);

      const funnelRows = [
        { label: '⏳ Pending Review', val: c.pendingReview || 0, color: '#fbbf24' },
        { label: '✅ Approved / Queued for Auto-Apply', val: c.approvedQueued || 0, color: '#34d399' },
        { label: '📤 Applied on Portals', val: c.applied || 0, color: '#38bdf8' },
        { label: '🎯 Interviewing & Assessments', val: c.interviewing || 0, color: '#c084fc' },
        { label: '🏆 Offers Received', val: c.offer || 0, color: '#10b981' },
        { label: '❌ Rejected / Closed', val: c.rejected || 0, color: '#fb7185' },
        { label: '⏸️ Skipped / Hold', val: c.skippedHold || 0, color: '#64748b' }
      ].sort((a, b) => b.val - a.val);

      const portalEntries = Object.entries(STATE.byPortal || {}).sort((a, b) => b[1] - a[1]).slice(0, 8);
      const maxPortal = Math.max(1, ...(portalEntries.map(x => x[1])));

      const catEntries = Object.entries(STATE.byCategory || {}).sort((a, b) => b[1] - a[1]);
      const maxCat = Math.max(1, ...(catEntries.map(x => x[1])));

      box.innerHTML = `
        <div class="chart-card">
          <div class="chart-title"><span>📊 Application Stage Funnel (Applies, Interviewing, Rejects)</span><span class="badge b-sky">${c.total || STATE.jobs.length} Total</span></div>
          <div class="chart-sub">Click any KPI card above to filter the Studio & Master Table by stage:</div>
          ${funnelRows.map(r => {
            const pct = Math.round((r.val / total) * 100);
            return `
              <div class="bar-row">
                <div class="bar-meta"><span>${r.label}</span><span class="mono">${r.val} (${pct}%)</span></div>
                <div class="bar-track"><div class="bar-fill" style="width:${Math.max(3, pct)}%; background:${r.color};"></div></div>
              </div>
            `;
          }).join('')}
        </div>

        <div class="chart-card">
          <div class="chart-title"><span>🌐 Top Job Portals Distribution</span><span class="badge b-purple">${Object.keys(STATE.byPortal || {}).length} Portals</span></div>
          <div class="chart-sub">Breakdown of sourced & applied opportunities across global and India job boards:</div>
          ${portalEntries.map(([name, cnt]) => {
            const pct = Math.round((cnt / maxPortal) * 100);
            return `
              <div class="bar-row">
                <div class="bar-meta"><span>${escHtml(name)}</span><span class="mono">${cnt} jobs</span></div>
                <div class="bar-track"><div class="bar-fill" style="width:${Math.max(5, pct)}%; background:linear-gradient(90deg, #38bdf8, #818cf8);"></div></div>
              </div>
            `;
          }).join('')}
        </div>

        <div class="chart-card">
          <div class="chart-title"><span>🎯 Role Category & Domain Breakdown</span><span class="badge b-emerald">80/20 Grounded</span></div>
          <div class="chart-sub">Distribution across Business Intelligence, Data Analytics, Product & Risk roles:</div>
          ${catEntries.map(([name, cnt]) => {
            const pct = Math.round((cnt / maxCat) * 100);
            return `
              <div class="bar-row">
                <div class="bar-meta"><span>${escHtml(name)}</span><span class="mono">${cnt} roles</span></div>
                <div class="bar-track"><div class="bar-fill" style="width:${Math.max(5, pct)}%; background:linear-gradient(90deg, #34d399, #0ea5e9);"></div></div>
              </div>
            `;
          }).join('')}
        </div>
      `;
    }

    // ============================================================================
    // LINKEDIN QUEUE, FRIENDS/HR NETWORK & RULES VAULT
    // ============================================================================
    function setLiFilter(status, search) {
      if (!STATE.liPrefs) STATE.liPrefs = { status: 'ALL', search: '' };
      if (status !== null && status !== undefined) STATE.liPrefs.status = status;
      if (search !== null && search !== undefined) STATE.liPrefs.search = search;
      renderLinkedInView();
    }

    function renderLinkedInView() {
      if (!STATE.liPrefs) STATE.liPrefs = { status: 'ALL', search: '' };
      const lp = STATE.liPrefs;
      const badge = document.getElementById('li-cookie-badge');
      const hasCookie = (STATE.socialSsoRows || []).some(r => r.site_name === 'SSO_Master_LinkedIn' && r.has_cookie) || STATE.hasLiCookie;
      if (badge) {
        badge.className = hasCookie ? 'badge b-emerald' : 'badge b-amber';
        badge.textContent = hasCookie ? '✅ li_at Cookie Active' : '⚠️ Manual 1-Tap Mode (Paste li_at to Automate)';
      }

      const allLogs = STATE.liLogs || [];
      const pendingCnt = allLogs.filter(x => /pending/i.test(x.approval_status || '')).length;
      const approvedCnt = allLogs.filter(x => /approved|reworked/i.test(x.approval_status || '') && !/rejected|denied/i.test(x.approval_status || '')).length;
      const sentCnt = allLogs.filter(x => /executed|confirmed|sent on linkedin/i.test(x.execution_status || '')).length;
      const rejectedCnt = allLogs.filter(x => /rejected|denied|skipped/i.test((x.approval_status || '') + ' ' + (x.execution_status || ''))).length;

      const ftb = document.getElementById('li-filter-toolbar');
      if (ftb) {
        ftb.innerHTML = `
          <div style="display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:8px;">
            <div style="display:flex; gap:6px; flex-wrap:wrap; align-items:center;">
              <button class="btn btn-sm ${lp.status==='ALL'?'btn-primary':''}" onclick="setLiFilter('ALL', null)">📋 All (${allLogs.length})</button>
              <button class="btn btn-sm ${lp.status==='PENDING'?'btn-primary':''}" onclick="setLiFilter('PENDING', null)">⏳ Pending (${pendingCnt})</button>
              <button class="btn btn-sm ${lp.status==='APPROVED'?'btn-primary':''}" onclick="setLiFilter('APPROVED', null)">✅ Approved / Reworked (${approvedCnt})</button>
              <button class="btn btn-sm ${lp.status==='SENT'?'btn-primary':''}" onclick="setLiFilter('SENT', null)">☑️ Sent (${sentCnt})</button>
              <button class="btn btn-sm ${lp.status==='REJECTED'?'btn-primary':''}" onclick="setLiFilter('REJECTED', null)">❌ Rejected (${rejectedCnt})</button>
            </div>
            <div style="display:flex; gap:8px; align-items:center; flex:1; max-width:520px; justify-content:flex-end;">
              <input type="text" id="li-search-inp" value="${escHtml(lp.search)}" placeholder="🔍 Search person, company, comment..." oninput="setLiFilter(null, this.value)" style="max-width:260px; padding:5px 10px; font-size:12px;" />
              <button class="btn btn-sm btn-emerald" onclick="shortenAllLiComments()" title="Ensure all comments & notes are crisp 8-13 word human 1-liners">✨ Enforce Short & Human On All</button>
            </div>
          </div>
        `;
      }

      const filtered = allLogs.filter(item => {
        const app = String(item.approval_status || '');
        const ex = String(item.execution_status || '');
        if (lp.status === 'PENDING' && !/pending/i.test(app)) return false;
        if (lp.status === 'APPROVED' && (!/approved|reworked/i.test(app) || /rejected|denied/i.test(app))) return false;
        if (lp.status === 'SENT' && !/executed|confirmed|sent on linkedin/i.test(ex)) return false;
        if (lp.status === 'REJECTED' && !/rejected|denied|skipped/i.test(app + ' ' + ex)) return false;
        if (lp.search && lp.search.trim()) {
          const q = lp.search.trim().toLowerCase();
          const hay = `${item.activity_id} ${item.company_name} ${item.insider_name} ${item.content_text} ${item.post_snippet}`.toLowerCase();
          if (!hay.includes(q)) return false;
        }
        return true;
      }).sort((a, b) => {
        const dCmp = String(b.activity_date || '').localeCompare(String(a.activity_date || ''));
        if (dCmp !== 0) return dCmp;
        const nA = parseInt(String(a.activity_id || '').replace(/[^0-9]/g, ''), 10) || 0;
        const nB = parseInt(String(b.activity_id || '').replace(/[^0-9]/g, ''), 10) || 0;
        return nB - nA;
      });

      const tbody = document.getElementById('li-table-tbody');
      if (!tbody) return;
      tbody.innerHTML = filtered.map(item => {
        const profUrl = item.target_profile_url || 'https://www.linkedin.com/in/';
        const postUrl = (item.linkedin_url && item.linkedin_url.startsWith('http')) ? item.linkedin_url : profUrl;
        const wordCount = String(item.content_text || '').trim().split(/\s+/).filter(Boolean).length;
        const isRejected = /rejected|denied/i.test(item.approval_status || '');
        const isApproved = /approved|reworked/i.test(item.approval_status || '') && !isRejected;
        const statusCls = isRejected ? 'b-rose' : (isApproved ? 'b-emerald' : 'b-amber');
        return `
          <tr style="${isRejected ? 'opacity:0.65;' : ''}">
            <td class="mono" style="white-space:nowrap;"><b style="font-size:12px; color:#f8fafc;">${escHtml(item.activity_date || '')}</b><br><span class="badge" style="font-size:9.5px; margin-top:4px;">${escHtml(item.activity_type || 'Comment')}</span></td>
            <td style="font-weight:700;">${escHtml(item.company_name)}</td>
            <td>
              <div style="font-weight:700;">${escHtml(item.insider_name)}</div>
              <a href="${escHtml(profUrl)}" target="_blank" style="color:#38bdf8; font-size:11.5px; font-weight:700;">🔗 Open Profile ↗</a>
            </td>
            <td>
              <a href="${escHtml(postUrl)}" target="_blank" class="btn btn-sm">🔗 Open Post ↗</a>
            </td>
            <td>
              <span class="badge b-sky">${escHtml(item.detected_sentiment || 'Analytical')}</span>
              <div style="font-size:11.5px; margin-top:4px;">${escHtml(item.reaction_type || '💡 Insightful')}</div>
            </td>
            <td style="min-width:350px; max-width:430px;">
              <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:4px;">
                <span class="badge ${wordCount <= 16 ? 'b-emerald' : 'b-amber'}" style="font-size:10px;">${wordCount} words • ${wordCount <= 16 ? 'Short & Human' : 'Review Length'}</span>
                ${item.learned_rule_feedback ? `<span style="font-size:10px; color:#c084fc; max-width:210px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;" title="${escHtml(item.learned_rule_feedback)}">🧠 ${escHtml(item.learned_rule_feedback)}</span>` : ''}
              </div>
              <div style="background:#060a14; padding:8px 10px; border-radius:8px; border:1px solid var(--border); font-size:12.5px; line-height:1.4; color:#f8fafc;">${escHtml(item.content_text)}</div>
              <div style="display:flex; gap:5px; margin-top:6px; align-items:center;">
                <input type="text" id="li-fb-inp-${escHtml(item.activity_id)}" placeholder="💬 Feedback / rule (e.g. 'Under 9 words & casual', 'Ask a question')..." style="flex:1; padding:4px 8px; font-size:11px; border-radius:6px; background:#090f1d; border:1px solid var(--border); color:#f8fafc;" onkeydown="if(event.key==='Enter') submitLiFeedback('${escHtml(item.activity_id)}', true)" />
                <button class="btn btn-sm" style="padding:3px 7px; font-size:10.5px; border-color:#38bdf8; color:#38bdf8;" onclick="submitLiFeedback('${escHtml(item.activity_id)}', false)" title="Rewrite this comment with LLM using your feedback">✨ Rewrite</button>
                <button class="btn btn-sm" style="padding:3px 7px; font-size:10.5px; border-color:#a855f7; color:#c084fc;" onclick="submitLiFeedback('${escHtml(item.activity_id)}', true)" title="Rewrite with LLM AND save as a permanent learned rule">🧠 +Learn</button>
              </div>
            </td>
            <td style="font-size:11.5px;">
              <span class="badge ${statusCls}">${escHtml(item.approval_status)}</span>
              <div style="color:${isRejected ? '#f43f5e' : '#34d399'}; margin-top:5px; font-size:11px;">${escHtml(item.execution_status)}</div>
            </td>
            <td style="white-space:nowrap;">
              <div style="display:flex; flex-direction:column; gap:5px;">
                <div style="display:flex; gap:4px;">
                  <button class="btn btn-sm" onclick="navigator.clipboard.writeText(${escAttrJson(item.content_text)}); showToast('Copied comment text!', '#10b981')" title="Copy text">📋 Copy</button>
                  <button class="btn btn-sm" onclick="promptEditLiComment('${escHtml(item.activity_id)}')" title="Edit comment text directly">✏️ Edit</button>
                  <button class="btn btn-sm" style="border-color:#a855f7; color:#c084fc;" onclick="focusOrPromptLiFeedback('${escHtml(item.activity_id)}')" title="Provide feedback so LLM rewrites & learns">💬 Feedback</button>
                </div>
                <div style="display:flex; gap:4px;">
                  <button class="btn btn-sm btn-primary" onclick="liItemAction('${escHtml(item.activity_id)}', 'approve')">✅ Approve</button>
                  <button class="btn btn-sm btn-emerald" onclick="liItemAction('${escHtml(item.activity_id)}', 'confirm_sent')">☑️ Sent</button>
                  <button class="btn btn-sm" style="border-color:#f43f5e; color:#fb7185;" onclick="rejectLiItem('${escHtml(item.activity_id)}')" title="Reject / Skip this comment (uses feedback box reason if typed)">❌ Reject</button>
                </div>
              </div>
            </td>
          </tr>
        `;
      }).join('');
    }

    function escAttrJson(val) {
      return JSON.stringify(String(val || '')).replace(/"/g, '&quot;');
    }

    async function liItemAction(activityId, subAction, extraPayload = {}) {
      try {
        const res = await callApi({ action: 'li_action', activityId, subAction, ...extraPayload });
        applyApiPayload(res);
        showToast(res.message || 'Updated LinkedIn activity!', '#10b981');
      } catch (e) {
        showToast('LinkedIn action error: ' + e.message, '#f43f5e');
      }
    }

    async function submitLiFeedback(activityId, learnRule = true) {
      const inp = document.getElementById('li-fb-inp-' + activityId);
      let feedback = (inp ? inp.value : '').trim();
      if (!feedback) {
        feedback = window.prompt('Enter your feedback for ' + activityId + ' (e.g. "Keep it under 10 words, casual and human", "Ask a question instead"):', 'Keep it short (under 11 words), impactful, and natural human tone') || '';
        if (!feedback.trim()) return;
      }
      if (inp) inp.disabled = true;
      showToast('🧠 LLM rewriting ' + activityId + (learnRule ? ' & synthesizing learned rule...' : '...'), '#38bdf8');
      try {
        const res = await callApi({ action: 'li_action', activityId, subAction: 'feedback_rewrite', feedback: feedback.trim(), learnRule });
        if (inp) { inp.value = ''; inp.disabled = false; }
        applyApiPayload(res);
        showToast(res.message || 'Rewrote comment & learned rule!', '#10b981');
      } catch (e) {
        if (inp) inp.disabled = false;
        showToast('Feedback error: ' + e.message, '#f43f5e');
      }
    }

    function focusOrPromptLiFeedback(activityId) {
      const inp = document.getElementById('li-fb-inp-' + activityId);
      if (inp && inp.value.trim()) {
        submitLiFeedback(activityId, true);
      } else {
        submitLiFeedback(activityId, true);
      }
    }

    async function rejectLiItem(activityId) {
      const inp = document.getElementById('li-fb-inp-' + activityId);
      const typedFb = (inp ? inp.value : '').trim();
      await liItemAction(activityId, 'deny', { feedback: typedFb });
    }

    async function promptEditLiComment(activityId) {
      const item = (STATE.liLogs || []).find(x => x.activity_id === activityId);
      if (!item) return;
      const updated = window.prompt('Edit comment / note for ' + item.insider_name + ' (' + item.company_name + '):', item.content_text || '');
      if (updated === null || !updated.trim()) return;
      await liItemAction(activityId, 'edit', { contentText: updated.trim(), learnRule: false });
    }

    async function shortenAllLiComments() {
      showToast('✨ Shortening all comments & notes to crisp 8-14 word human 1-liners...', '#38bdf8');
      await liItemAction('ALL', 'shorten_all_comments');
    }

