          replyText: txt.trim(),
          senderRole: 'them'
        });
        applyApiPayload(res);
        showToast(res.message || 'Logged member message!', '#10b981');
      } catch (e) {
        showToast('Error logging message: ' + e.message, '#f43f5e');
      }
    }

    async function syncFhInbox() {
      showToast('🔄 Syncing LinkedIn Member Messages & Voyager Inbox...', '#38bdf8');
      try {
        const res = await callApi({ action: 'fh_action', subAction: 'sync_inbox' });
        applyApiPayload(res);
        showToast(res.message || 'Synced LinkedIn member messages!', '#10b981');
      } catch (e) {
        showToast('Sync error: ' + e.message, '#f43f5e');
      }
    }

    async function promptSaveLiCookie() {
      const val = window.prompt('Paste your LinkedIn "li_at" session cookie (from Chrome DevTools -> Application -> Cookies -> linkedin.com -> li_at) to enable 100% automatic background Voyager DM sending & inbox sync:', '');
