    STATE.portalDatePreset = STATE.portalDatePreset || 'yesterday';
    STATE.portalCustomFrom = STATE.portalCustomFrom || '';
    STATE.portalCustomTo = STATE.portalCustomTo || '';
    STATE.portalActivityFilter = STATE.portalActivityFilter || 'all';
