    STATE.expandedPortal = STATE.expandedPortal || '';

    function parseJobIsoDate(raw) {
      const s = String(raw || '').trim();
      if (!s) return '';
      const mIso = s.match(/^(\d{4}-\d{2}-\d{2})/);
      if (mIso) return mIso[1];
      const mSlash = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/);
      if (mSlash) {
        const mo = String(mSlash[1]).padStart(2, '0');
        const dy = String(mSlash[2]).padStart(2, '0');
        return `${mSlash[3]}-${mo}-${dy}`;
      }
      return '';
    }

    function getPortalDateBounds() {
      const nowIst = new Date(Date.now() + 5.5 * 3600 * 1000);
      const toIso = (d) => d.toISOString().slice(0, 10);
      const todayIso = toIso(nowIst);
      const yest = new Date(nowIst.getTime() - 86400000);
      const yesterdayIso = toIso(yest);
      const d7 = new Date(nowIst.getTime() - 6 * 86400000);
      const last7Iso = toIso(d7);
      const d30 = new Date(nowIst.getTime() - 29 * 86400000);
      const last30Iso = toIso(d30);
      const monthStartIso = todayIso.slice(0, 8) + '01';
      return { todayIso, yesterdayIso, last7Iso, last30Iso, monthStartIso };
    }

    function dateMatchesPortalFilter(isoDate, preset, b) {
      if (!isoDate) return false;
      if (preset === 'today') return isoDate === b.todayIso;
      if (preset === 'yesterday') return isoDate === b.yesterdayIso;
      if (preset === 'last7') return isoDate >= b.last7Iso && isoDate <= b.todayIso;
      if (preset === 'last30') return isoDate >= b.last30Iso && isoDate <= b.todayIso;
      if (preset === 'month') return isoDate >= b.monthStartIso && isoDate <= b.todayIso;
      if (preset === 'custom') {
        const f = STATE.portalCustomFrom || '2000-01-01';
        const t = STATE.portalCustomTo || '2099-12-31';
        return isoDate >= f && isoDate <= t;
      }
      return true;
    }

    function mapJobToPortalName(j) {
      const p = String(j.portal || '').toLowerCase();
      const c = String(j.company || '').toLowerCase();
      const u = String(j.jdUrl || '').toLowerCase();
      if (c === 'jobgether' || p.includes('jobgether') || u.includes('jobgether')) return 'Jobgether';
      if (p.includes('→ company career site') || p === 'company site' || p.includes('queued (company career site)')) return 'Company Career Sites (Direct)';
      if (p.includes('naukri gulf') || u.includes('naukrigulf')) return 'Naukri Gulf';
      if (p.includes('naukri') || u.includes('naukri.com')) return 'Naukri';
      if (p.includes('wellfound') || u.includes('wellfound')) return 'Wellfound';
      if (p.includes('indeed') || u.includes('indeed')) return 'Indeed';
      if (p.includes('remotive') || u.includes('remotive')) return 'Remotive';
      if (p.includes('linkedin') || u.includes('linkedin.com')) return 'LinkedIn Jobs';
      if (c === 'jobgether' || p.includes('jobgether') || u.includes('jobgether')) return 'Jobgether';
      if (p.includes('cutshort') || u.includes('cutshort')) return 'Cutshort';
      if (p.includes('instahyre') || u.includes('instahyre')) return 'Instahyre';
      if (p.includes('hirist') || u.includes('hirist')) return 'hirist';
      if (p.includes('himalayas') || u.includes('himalayas')) return 'Himalayas';
      if (p.includes('builtin') || p.includes('built in') || u.includes('builtin')) return 'BuiltIn (Remote & India)';
      if (p.includes('glassdoor') || u.includes('glassdoor')) return 'Glassdoor';
      if (p.includes('foundit') || u.includes('foundit')) return 'foundit (Monster)';
      if (p.includes('monster') || u.includes('monster')) return 'Monster';
      if (p.includes('shine') || u.includes('shine.com')) return 'Shine';
      if (p.includes('times') || u.includes('timesjobs')) return 'Times Jobs';
      if (p.includes('remoteok') || u.includes('remoteok')) return 'RemoteOK';
      if (p.includes('weworkremotely')) return 'WeWorkRemotely';
      if (p.includes('working nomads')) return 'Working Nomads';
      if (p.includes('combinator') || u.includes('workatastartup')) return 'Y combinator';
      if (p.includes('referral') || p.includes('email')) return 'Referral & Direct Email';
      if (p.includes('company site') || p.includes('career site') || p.includes('direct')) return 'Company Career Sites (Direct)';
      return 'Company Career Sites (Direct)';
    }

