    async function addLearnedRule() {
      const instr = (document.getElementById('rule-new-text')?.value || '').trim();
      if (!instr) return;
      try {
        const res = await callApi({
          action: 'rule_action',
          subAction: 'add',
          sectionName: document.getElementById('rule-new-sec')?.value || 'global',
          ruleInstruction: instr
        });
        document.getElementById('rule-new-text').value = '';
        applyApiPayload(res);
        showToast(res.message || 'Saved permanent learned rule!', '#10b981');
      } catch (e) {
        showToast('Rule error: ' + e.message, '#f43f5e');
      }
    }

    async function deleteLearnedRule(ruleId) {
      try {
        const res = await callApi({ action: 'rule_action', subAction: 'delete', ruleId });
        applyApiPayload(res);
        showToast(res.message || 'Deleted rule.', '#f59e0b');
      } catch (e) {
        showToast('Delete error: ' + e.message, '#f43f5e');
      }
