      try {
        const res = await callApi({ action: 'trigger_batch_25' });
        showToast(res.message || 'Triggered 25-job batch generation!', res.ok ? '#10b981' : '#f59e0b');
      } catch (e) {
        showToast('Trigger error: ' + e.message, '#f43f5e');
      } finally {
        if (btn) { btn.disabled = false; btn.textContent = orig || '⚡ Generate new jobs'; }
      }
    }

