-- Ensure user_id column exists across all tenant tables and enforce PostgreSQL Row-Level Security (RLS)
ALTER TABLE resume_generations ADD COLUMN IF NOT EXISTS user_id INT DEFAULT 1;
ALTER TABLE cover_letter_generations ADD COLUMN IF NOT EXISTS user_id INT DEFAULT 1;
ALTER TABLE learned_rules ADD COLUMN IF NOT EXISTS user_id INT DEFAULT 1;
