// sergebulaev/linkedin-skills V3 Humanizer + T1-T7 / R1-R5 Engine
function humanizeLinkedInTextV3(rawText) {
  let out = String(rawText || '').trim();
  if (!out) return out;
  const bannedOpeners = [/^Great\s+post[!.,\s]*/i, /^Love\s+this[!.,\s]*/i, /^This\s+is\s+so\s+true[!.,\s]*/i, /^100%[!.,\s]*/i, /\bLet\s+that\s+sink\s+in\.?/gi, /\bRead\s+that\s+again\.?/gi, /\bThe\s+result\?\s*/gi, /\bThe\s+kicker\?\s*/gi, /\bHere'?s\s+the\s+thing:\s*/gi, /\bLet\s+me\s+be\s+honest[,:\s]*/gi, /\bUnpopular\s+opinion:\s*/gi];
  for (const pat of bannedOpeners) out = out.replace(pat, '').trim();
  const vocabMap = [[/\bleveraging\b/gi, 'using'], [/\bleverage\b/gi, 'use'], [/\butilizing\b/gi, 'using'], [/\butilize\b/gi, 'use'], [/\bdelve(\s+into)?\b/gi, 'dig into'], [/\bfoster(ing)?\b/gi, 'build'], [/\bstreamline\b/gi, 'simplify'], [/\belevate\b/gi, 'improve'], [/\bempower(ing)?\b/gi, 'help'], [/\blandscape\b/gi, 'space'], [/\bholistic\b/gi, 'end-to-end'], [/\brobust\b/gi, 'solid'], [/\bseamless(ly)?\b/gi, 'smooth'], [/\bgame-changer\b/gi, 'shift']];
  for (const [pat, repl] of vocabMap) out = out.replace(pat, repl);
  out = out.replace(/\s+—\s+/g, '.. ').replace(/\s+/g, ' ').trim();
  if (out && /^[a-z]/.test(out)) out = out[0].toUpperCase() + out.slice(1);
  return out;
}


