async function tryVoyagerSyncInbox(cookie, contactsList) {
  if (!cookie || cookie.length < 20) return { syncedCount: 0, apiConnected: false };
  const csrf = 'ajax:8841920394810293841';
  const headers = {
    'Cookie': `li_at=${cookie}; JSESSIONID="${csrf}"`,
    'csrf-token': csrf,
    'x-restli-protocol-version': '2.0.0',
    'User-Agent': 'Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0.0.0 Safari/537.36'
  };
  try {
    const inbox = await _wf8Ctx.helpers.httpRequest({
      method: 'GET',
      url: 'https://www.linkedin.com/voyager/api/messaging/conversations?keyVersion=LEGACY_INBOX',
      headers,
      json: true,
      timeout: 7000
    });
    const elements = Array.isArray(inbox?.elements) ? inbox.elements : [];
    let syncedCount = 0;
    for (const conv of elements) {
      const convUrn = conv.entityUrn || '';
      const parts = Array.isArray(conv.participants) ? conv.participants : [];
      for (const p of parts) {
        const mp = p['com.linkedin.voyager.messaging.MessagingMember']?.miniProfile;
        if (!mp) continue;
        const pubId = String(mp.publicIdentifier || '').toLowerCase();
        const fullName = `${mp.firstName || ''} ${mp.lastName || ''}`.trim().toLowerCase();
        const match = contactsList.find(c => {
          const cUrl = String(c.target_profile_url || '').toLowerCase();
          const cName = String(c.person_name || '').toLowerCase();
          return (pubId && cUrl.includes(`/in/${pubId}`)) || (fullName.length > 4 && cName === fullName);
        });
        if (match) {
          match.conversation_urn = convUrn;
          const evs = Array.isArray(conv.events) ? conv.events : [];
          for (const ev of evs) {
            const txt = ev?.eventContent?.['com.linkedin.voyager.messaging.event.MessageEvent']?.attributedBody?.text
              || ev?.eventContent?.['com.linkedin.voyager.messaging.event.MessageEvent']?.body || '';
            if (txt && !match.messages.some(m => m.text === txt)) {
              const fromMp = ev?.from?.['com.linkedin.voyager.messaging.MessagingMember']?.miniProfile;
              const isFromThem = fromMp && String(fromMp.publicIdentifier || '').toLowerCase() === pubId;
              match.messages.push({
                sender: isFromThem ? 'them' : 'me',
                author: isFromThem ? match.person_name : 'You (Sumanto)',
                text: txt,
                ts: new Date(ev.createdAt || Date.now()).toISOString().slice(0, 16).replace('T', ' '),
                channel: 'LinkedIn Voyager Inbox',
                status: isFromThem ? 'Received' : 'Sent on LinkedIn'
              });
              syncedCount++;
            }
          }
          match.messages_json = JSON.stringify(match.messages);
        }
      }
    }
    return { syncedCount, apiConnected: true };
  } catch (e) {
    return { syncedCount: 0, apiConnected: false };
  }
}

