      if (subAction === 'approve') {
        c.approval_status = 'Approved';
        c.execution_status = '⏳ Approved — Tap Profile Link to Connect';
        c.outreach_stage = 'Approved — Ready to Connect';
        apiMessage = `✅ Approved ${cId} (${c.person_name})! Click their Profile Link, paste the note, and click Confirm Sent.`;
