        c.approval_status = 'Approved';
        c.execution_status = `Executed (Confirmed Sent ${todayIso})`;
        c.outreach_stage = 'Connection / Message Sent';
        sqlQueries.push(`UPDATE linkedin_daily_stats SET connection_requests_sent = connection_requests_sent + 1, updated_at = NOW() WHERE stat_date = CURRENT_DATE;`);
        apiMessage = `☑️ Confirmed ${cId} (${c.person_name}) as Sent on LinkedIn!`;
      } else if (subAction === 'skip' || subAction === 'deny' || subAction === 'reject') {
        const fb = String(body.feedback || '').trim();
        c.approval_status = fb ? 'Rejected & Rule Learned' : 'Rejected / Skipped';
        c.execution_status = 'Skipped by User';
        if (fb) {
          const synth = synthesizeLlmRule(fb, 'LinkedIn Post');
          sqlQueries.push(`INSERT INTO learned_rules (section_name, role_category, rule_instruction, triggered_by_comment, is_active) VALUES ('LinkedIn Post', 'LinkedIn Networking', '${esc(synth.rule)}', '${esc(cId)}', TRUE);`);
          allLearnedRules.unshift({ id: Date.now(), section_name: 'LinkedIn Post', role_category: 'LinkedIn Networking', rule_instruction: synth.rule, is_active: true });
          apiMessage = `❌ Rejected ${cId} (${c.person_name}) & saved learned rule!`;
        } else {
          apiMessage = `❌ Marked ${cId} (${c.person_name}) as Rejected / Skipped.`;
        }
      } else if (subAction === 'feedback_rewrite') {
        const fb = String(body.feedback || '').trim();
        const learn = body.learnRule !== undefined ? Boolean(body.learnRule) : true;
        const first = String(c.person_name || 'there').split(' ')[0];
        const comp = String(c.company_name || 'your team').split('/')[0].trim();
        let newNote = String(llmOut.rewritten_comment || '').trim();
        if (!newNote) {
          newNote = `Hi ${first}, great seeing your analytics work at ${comp}—would love to connect!`;
        }
        c.connection_note = newNote;
        c.approval_status = learn ? 'Reworked & Rule Learned' : 'Reworked';
        if (Array.isArray(c.messages) && c.messages.length > 0 && c.messages[0].sender === 'me') {
          c.messages[0].text = newNote;
          c.messages_json = JSON.stringify(c.messages);
        }
        if (learn && fb) {
          const synth = synthesizeLlmRule(fb, 'LinkedIn Post');
          sqlQueries.push(`INSERT INTO learned_rules (section_name, role_category, rule_instruction, triggered_by_comment, is_active) VALUES ('LinkedIn Post', 'LinkedIn Networking', '${esc(synth.rule)}', '${esc(cId)}', TRUE);`);
          allLearnedRules.unshift({ id: Date.now(), section_name: 'LinkedIn Post', role_category: 'LinkedIn Networking', rule_instruction: synth.rule, is_active: true });
        }
        apiMessage = `✨ Rewrote note for ${c.person_name}: "${newNote}"`;
      } else if (subAction === 'edit') {
        c.connection_note = String(body.connectionNote || c.connection_note || '').trim();
        if (body.category) c.category = String(body.category).trim();
        if (body.location) c.location = String(body.location).trim();
        apiMessage = `Updated reach-out note for ${cId} (${c.person_name})!`;
      } else if (subAction === 'toggle_star') {
        const curNotes = String(c.notes_log || '');
        if (curNotes.includes('[STARRED]')) {
          c.notes_log = curNotes.replace('[STARRED]', '').trim();
          apiMessage = `Removed ⭐ Priority Star from ${c.person_name} (${c.company_name}).`;
        } else {
          c.notes_log = `[STARRED] ${curNotes}`.trim();
          apiMessage = `⭐ Starred ${c.person_name} (${c.company_name}) as Priority Contact!`;
        }
      } else if (subAction === 'send_reply') {
        const replyText = String(body.replyText || '').trim();
        const senderRole = String(body.senderRole || 'me').trim();
        if (replyText) {
          let voyRes = { sentViaApi: false, statusLabel: 'Received (Logged)', convUrn: c.conversation_urn || '' };
          if (senderRole !== 'them') {
            voyRes = await tryVoyagerSendReply(liAtCookie, c, replyText);
