          if (voyRes.convUrn) c.conversation_urn = voyRes.convUrn;
          c.messages = Array.isArray(c.messages) ? c.messages : [];
          c.messages.push({
            sender: senderRole === 'them' ? 'them' : 'me',
            author: senderRole === 'them' ? c.person_name : 'You (Sumanto)',
            text: replyText,
            ts: nowIstStamp,
            channel: senderRole === 'them' ? 'LinkedIn Member Reply' : (voyRes.sentViaApi ? 'LinkedIn Voyager API' : 'Workflow Reply Queue'),
            status: voyRes.statusLabel
          });
          c.messages_json = JSON.stringify(c.messages);
          if (senderRole !== 'them') {
            c.connection_note = replyText;
            c.approval_status = 'Approved & Replied';
            c.execution_status = voyRes.statusLabel;
            c.outreach_stage = voyRes.sentViaApi ? 'Replied on LinkedIn (API Verified)' : 'Reply Queued / Ready to Send';
            sqlQueries.push(`UPDATE linkedin_daily_stats SET messages_sent = messages_sent + 1, updated_at = NOW() WHERE stat_date = CURRENT_DATE;`);
            apiMessage = voyRes.sentViaApi
              ? `✅ Sent reply to ${c.person_name} (${c.company_name}) directly on LinkedIn via Voyager API!`
              : `📤 Logged reply to ${c.person_name} (${c.company_name}) & copied to clipboard! (Connect li_at cookie for 100% direct API send, or click Open DM to paste).`;
