  else if (j.stageBucket === 'Skipped / Hold') counts.skippedHold++;

  if (j.clDriveId || j.clSections?.hasStoredCl) counts.withCoverLetter++;
  if (j.reference || j.hrName || j.hrEmail) counts.withReferral++;

  const rawP = String(j.portal || '').toLowerCase();
  let cleanP = 'Company Career Sites (Direct)';
  if (rawP.includes('→ company career site') || rawP === 'company site' || rawP.includes('queued (company career site)')) cleanP = 'Company Career Sites (Direct)';
  else if (rawP.includes('instahyre')) cleanP = 'Instahyre';
  else if (rawP.includes('naukri gulf')) cleanP = 'Naukri Gulf';
  else if (rawP.includes('naukri')) cleanP = 'Naukri';
  else if (rawP.includes('wellfound')) cleanP = 'Wellfound';
  else if (rawP.includes('indeed')) cleanP = 'Indeed';
  else if (rawP.includes('linkedin')) cleanP = 'LinkedIn Jobs';
  else if (rawP.includes('hirist')) cleanP = 'hirist';
  else if (rawP.includes('cutshort')) cleanP = 'Cutshort';
  else if (rawP.includes('foundit')) cleanP = 'foundit (Monster)';
  else if (rawP.includes('remotive')) cleanP = 'Remotive';
  else if (rawP.includes('himalayas')) cleanP = 'Himalayas';
  else if (rawP.includes('jobgether') || String(j.company || '').toLowerCase() === 'jobgether') cleanP = 'Jobgether';
  else if (rawP.includes('builtin') || rawP.includes('built in')) cleanP = 'BuiltIn (Remote & India)';
  else if (rawP.includes('referral') || rawP.includes('email')) cleanP = 'Referral & Direct Email';
  byPortal[cleanP] = (byPortal[cleanP] || 0) + 1;

  const cName = j.roleCategory || 'Data & Business Analytics';
  byCategory[cName] = (byCategory[cName] || 0) + 1;
}
// Enforce strict descending order on byPortal and byCategory at the API layer
for (const obj of [byPortal, byCategory]) {
  const entries = Object.entries(obj).sort((a, b) => Number(b[1] || 0) - Number(a[1] || 0));
  for (const k of Object.keys(obj)) delete obj[k];
  for (const [k, v] of entries) obj[k] = v;
}

